// fa4_qk_2sm.cu — Blackwell SM100 2-SM (cta_group::2) QK GEMM building block.
//
// Validates the core FA4-2SM primitive: a 2-CTA cluster collaborates on ONE 256x128x128 UMMA.
//   - A (Q) [M=256,K=128] is split by M across the pair: CTA0 rows[0:128], CTA1 rows[128:256].
//   - B (K) [N=128,K=128] is split by N across the pair: CTA0 keys[0:64], CTA1 keys[64:128].
//   - Only the leader CTA (cluster rank 0) issues tcgen05.mma.cta_group::2 (8-elem zero disable mask).
//   - commit.cta_group::2.multicast signals BOTH CTAs' mbarrier at the same smem offset.
//   - Accumulator C [256,128] is split by M: CTA0 tmem holds rows[0:128], CTA1 rows[128:256].
// Each CTA reads back its own 128 rows and we check vs an fp32 reference.
//
// idesc(2SM QK) = 0x10200490: 1SM QK idesc 0x8200490 with m_dim 8->16 (M=128->256).
//
// Build: nvcc -gencode arch=compute_100a,code=sm_100a -O3 -std=c++17 fa4_qk_2sm.cu -o /tmp/qk2sm
#include "probe_common.cuh"

__device__ __forceinline__ uint32_t smem_u32(const void* p){ return (uint32_t)__cvta_generic_to_shared(p); }
__device__ __forceinline__ void tmem_alloc2(uint32_t s,int n){ asm volatile("tcgen05.alloc.cta_group::2.sync.aligned.shared::cta.b32 [%0], %1;"::"r"(s),"r"(n)); }
__device__ __forceinline__ void tmem_relinquish2(){ asm volatile("tcgen05.relinquish_alloc_permit.cta_group::2.sync.aligned;"); }
__device__ __forceinline__ void tmem_dealloc2(uint32_t a,int n){ asm volatile("tcgen05.dealloc.cta_group::2.sync.aligned.b32 %0, %1;"::"r"(a),"r"(n)); }
__device__ __forceinline__ uint32_t tmem_ld_1(uint32_t a){ uint32_t v; asm volatile("tcgen05.ld.sync.aligned.32x32b.x1.b32 {%0}, [%1];":"=r"(v):"r"(a)); return v; }
__device__ __forceinline__ void tmem_wait_ld(){ asm volatile("tcgen05.wait::ld.sync.aligned;"); }

// 128B swizzle (K-major, ROWS<=128 tile) — byte-identical to the 1SM probe.
__device__ __forceinline__ int koff(int row,int c){ return (c>>6)*8192 + row*64 + ((c&63) ^ ((row&7)<<3)); }
__device__ __forceinline__ uint64_t make_desc_sm100(uint32_t addr,uint32_t lbo,uint32_t sbo,int lt){
    uint64_t d=0; d|=(uint64_t)((addr>>4)&0x3FC0u); d|=(uint64_t)((lbo>>4)&0x3FFFu)<<16;
    d|=(uint64_t)((sbo>>4)&0x3FFFu)<<32; d|=(uint64_t)1u<<46; d|=(uint64_t)(lt&0x7u)<<61; return d; }
__device__ __forceinline__ uint64_t desc_add(uint64_t b,uint32_t off){
    uint32_t lo,hi; asm("mov.b64 {%0,%1}, %2;":"=r"(lo),"=r"(hi):"l"(b));
    lo+=off; uint64_t r; asm("mov.b64 %0,{%1,%2};":"=l"(r):"r"(lo),"r"(hi)); return r; }
__device__ __forceinline__ uint32_t qk_doff(int kb){ return (uint32_t)((kb&3)*2 + (kb>>2)*1024); }

constexpr int M=256, N=128, K=128, NKT=K/16;   // 2 CTAs x 128 rows; 8 k-tiles of MMA-K=16
constexpr int MH=M/2, NH=N/2;                  // per-CTA halves: 128 rows of Q, 64 keys of K
constexpr uint32_t QK_IDESC_2SM = 0x10200490u; // m_dim=16 (M=256), n_dim=16 (N=128), bf16, F32 acc, K-major

__global__ void __cluster_dims__(2,1,1) __launch_bounds__(128)
qk2sm_kernel(const __nv_bfloat16* Qg, const __nv_bfloat16* Kg, float* Sout){
    __shared__ __align__(1024) __nv_bfloat16 sQ[MH*K];   // this CTA's 128 Q rows
    __shared__ __align__(1024) __nv_bfloat16 sK[NH*K];   // this CTA's 64 K keys
    __shared__ __align__(8) uint32_t s_base;
    __shared__ __align__(8) uint64_t s_mbar;
    const int tid=threadIdx.x, warp=tid>>5;
    const int rank=blockIdx.x&1;                 // cluster rank (grid=2, cluster=2 -> blockIdx.x is rank)
    const bool leader=(rank==0);

    // 1) fill this CTA's swizzled smem halves.
    for(int i=tid;i<MH*K;i+=128){ int r=i/K,c=i%K; sQ[koff(r,c)] = Qg[(rank*MH + r)*K + c]; }
    for(int i=tid;i<NH*K;i+=128){ int r=i/K,c=i%K; sK[koff(r,c)] = Kg[(rank*NH + r)*K + c]; }
    asm volatile("fence.proxy.async.shared::cta;");
    __syncthreads();

    // 2) collective 2SM tmem alloc (warp0 on BOTH CTAs, same dst_ptr) + mbar init (both CTAs).
    if(warp==0) tmem_alloc2(smem_u32(&s_base), 512);
    if(warp==0) tmem_relinquish2();
    if(tid==0) asm volatile("mbarrier.init.shared.b64 [%0], 1;"::"r"(smem_u32(&s_mbar)));
    __syncthreads();
    const uint32_t base=s_base;

    // 3) leader CTA issues the 2SM MMA (8 k-tiles) then multicast-commits to both CTAs' mbar.
    if(leader && warp==0){
        uint64_t qd0=make_desc_sm100(smem_u32(sQ),16,1024,2);
        uint64_t kd0=make_desc_sm100(smem_u32(sK),16,1024,2);
        for(int kb=0;kb<NKT;++kb){
            uint64_t qd=desc_add(qd0,qk_doff(kb)), kd=desc_add(kd0,qk_doff(kb));
            uint32_t sc=(kb>0)?1u:0u;   // accumulate flag: 0 on first k-tile, 1 after
            asm volatile(
                "{ .reg .pred lead; .reg .pred p;\n"
                "  elect.sync _|lead,-1;\n"
                "  setp.ne.b32 p, %4, 0;\n"
                "  @lead tcgen05.mma.cta_group::2.kind::f16 [%0], %1, %2, %3, {%5,%6,%7,%8,%9,%10,%11,%12}, p;\n"
                "}" :: "r"(base),"l"(qd),"l"(kd),"r"(QK_IDESC_2SM),"r"(sc),
                      "r"(0u),"r"(0u),"r"(0u),"r"(0u),"r"(0u),"r"(0u),"r"(0u),"r"(0u));
        }
        asm volatile(
            "{ .reg .pred lead;\n"
            "  elect.sync _|lead,-1;\n"
            "  @lead tcgen05.commit.cta_group::2.mbarrier::arrive::one.shared::cluster.multicast::cluster.b64 [%0], %1;\n"
            "}" :: "r"(smem_u32(&s_mbar)), "r"(0x3u));   // ctaMask = both CTAs in the cluster
    }

    // 4) all threads (both CTAs) wait for MMA completion on the local mbar (phase 0).
    asm volatile(
        "{ .reg .pred P;\n"
        "LW: mbarrier.try_wait.parity.shared.b64 P,[%0],0,10000000;\n"
        "  @P bra D; bra LW;\n"
        "D: }" :: "r"(smem_u32(&s_mbar)));
    __syncthreads();

    // 5) each CTA reads back its 128 rows: tmem lane=tid -> global row rank*128 + tid.
    for(int c=0;c<N;++c){
        uint32_t taddr=base + ((uint32_t)tid<<16) + (uint32_t)c;
        uint32_t bits=tmem_ld_1(taddr); tmem_wait_ld();
        float v; memcpy(&v,&bits,4);
        Sout[(rank*MH + tid)*N + c]=v;
    }
    __syncthreads();
    if(warp==0) tmem_dealloc2(base,512);
}

int main(){
    ORC_CHECK(cudaSetDevice(0));
    cudaDeviceProp p{}; ORC_CHECK(cudaGetDeviceProperties(&p,0));
    std::printf("device: %s cc %d.%d\n", p.name, p.major, p.minor);

    std::vector<uint16_t> Qh,Kh; orc::fill_bf16(Qh,M*K,1); orc::fill_bf16(Kh,N*K,2);
    __nv_bfloat16 *dQ,*dK; float* dS;
    ORC_CHECK(cudaMalloc(&dQ,M*K*2)); ORC_CHECK(cudaMalloc(&dK,N*K*2)); ORC_CHECK(cudaMalloc(&dS,M*N*4));
    ORC_CHECK(cudaMemcpy(dQ,Qh.data(),M*K*2,cudaMemcpyHostToDevice));
    ORC_CHECK(cudaMemcpy(dK,Kh.data(),N*K*2,cudaMemcpyHostToDevice));

    qk2sm_kernel<<<dim3(2,1,1),128>>>(dQ,dK,dS);
    ORC_CHECK(cudaGetLastError()); ORC_CHECK(cudaDeviceSynchronize());

    std::vector<float> S(M*N); ORC_CHECK(cudaMemcpy(S.data(),dS,M*N*4,cudaMemcpyDeviceToHost));

    double max_abs=0,max_rel=0; int shown=0;
    for(int m=0;m<M;++m) for(int n=0;n<N;++n){
        double acc=0;
        for(int k=0;k<K;++k) acc += (double)orc::bf16_bits_to_f32(Qh[m*K+k]) * (double)orc::bf16_bits_to_f32(Kh[n*K+k]);
        double got=S[m*N+n], err=std::fabs(got-acc), rel=err/(std::fabs(acc)+1e-6);
        if(err>max_abs) max_abs=err; if(rel>max_rel) max_rel=rel;
        if(err>0.5 && shown<8){ std::printf("  bad m=%d n=%d got=%.4f ref=%.4f\n",m,n,got,acc); shown++; }
    }
    std::printf("max_abs=%.5f  max_rel=%.5f\n",max_abs,max_rel);
    bool pass=(max_abs<0.5);
    std::printf("%s: 2SM QK GEMM (cta_group::2, split A by M / B by N, per-CTA readback)\n", pass?"PASS":"FAIL");
    ORC_CHECK(cudaFree(dQ)); ORC_CHECK(cudaFree(dK)); ORC_CHECK(cudaFree(dS));
    return pass?0:1;
}

// fa4_attn_2sm.cu — Blackwell SM100 2-SM (cta_group::2) SINGLE-BLOCK attention compute chain.
//
// Validates the full 2SM compute core end-to-end: 2-CTA cluster does one 256-row attention block:
//   QK (cta_group::2, K split by keys) -> per-CTA softmax over its 128 rows -> P (bf16) in tmem
//   -> PV (cta_group::2, TS form, V split by HDV) -> O in tmem -> readback, check vs fp32 softmax(QK^T)V.
// No pipeline / online update (1 block). Proves: 2SM PV (TS + MN-major V split), P-from-tmem cross-CTA,
// and that both MMAs share the distributed accumulator correctly.
//
// Build: nvcc -gencode arch=compute_100a,code=sm_100a -O3 -std=c++17 fa4_attn_2sm.cu -o /tmp/attn2sm
#include "probe_common.cuh"
#include <cuda_bf16.h>

__device__ __forceinline__ uint32_t smem_u32(const void* p){ return (uint32_t)__cvta_generic_to_shared(p); }
__device__ __forceinline__ void tmem_alloc2(uint32_t s,int n){ asm volatile("tcgen05.alloc.cta_group::2.sync.aligned.shared::cta.b32 [%0], %1;"::"r"(s),"r"(n)); }
__device__ __forceinline__ void tmem_relinquish2(){ asm volatile("tcgen05.relinquish_alloc_permit.cta_group::2.sync.aligned;"); }
__device__ __forceinline__ void tmem_dealloc2(uint32_t a,int n){ asm volatile("tcgen05.dealloc.cta_group::2.sync.aligned.b32 %0, %1;"::"r"(a),"r"(n)); }
__device__ __forceinline__ uint32_t tmem_ld(uint32_t a){ uint32_t v; asm volatile("tcgen05.ld.sync.aligned.32x32b.x1.b32 {%0}, [%1];":"=r"(v):"r"(a)); return v; }
__device__ __forceinline__ void tmem_st(uint32_t a,uint32_t v){ asm volatile("tcgen05.st.sync.aligned.32x32b.x1.b32 [%0], {%1};"::"r"(a),"r"(v)); }
__device__ __forceinline__ void tmem_wait_ld(){ asm volatile("tcgen05.wait::ld.sync.aligned;"); }
__device__ __forceinline__ void tmem_wait_st(){ asm volatile("tcgen05.wait::st.sync.aligned;"); }
__device__ __forceinline__ void tmem_fence(){ asm volatile("tcgen05.fence::after_thread_sync;"); }
__device__ __forceinline__ float ex2f(float x){ float r; asm volatile("ex2.approx.ftz.f32 %0,%1;":"=f"(r):"f"(x)); return r; }
__device__ __forceinline__ uint32_t pack16b(float a,float b){ __nv_bfloat162 v=__floats2bfloat162_rn(a,b); uint32_t r; memcpy(&r,&v,4); return r; }

__device__ __forceinline__ int koff(int row,int c){ return (c>>6)*8192 + row*64 + ((c&63)^((row&7)<<3)); }   // K-major (Q,K)
__device__ __forceinline__ int voff(int key,int dv){ return (dv>>6)*8192 + key*64 + ((dv&63)^((key&7)<<3)); } // MN-major (V)
__device__ __forceinline__ uint64_t make_desc(uint32_t a,uint32_t lbo,uint32_t sbo,int lt){
    uint64_t d=0; d|=(uint64_t)((a>>4)&0x3FC0u); d|=(uint64_t)((lbo>>4)&0x3FFFu)<<16;
    d|=(uint64_t)((sbo>>4)&0x3FFFu)<<32; d|=(uint64_t)1u<<46; d|=(uint64_t)(lt&0x7u)<<61; return d; }
__device__ __forceinline__ uint64_t desc_add(uint64_t b,uint32_t off){
    uint32_t lo,hi; asm("mov.b64 {%0,%1}, %2;":"=r"(lo),"=r"(hi):"l"(b));
    lo+=off; uint64_t r; asm("mov.b64 %0,{%1,%2};":"=l"(r):"r"(lo),"r"(hi)); return r; }
__device__ __forceinline__ uint32_t qk_doff(int kb){ return (uint32_t)((kb&3)*2 + (kb>>2)*1024); }
__device__ __forceinline__ uint32_t v_doff(int kb){ return (uint32_t)(kb*0x80); }

constexpr int M=256, N=128, HD=128, HDV=128;
constexpr int MH=M/2, NH=N/2, HDVH=HDV/2;               // per-CTA halves
constexpr int NKT_QK=HD/16, NKT_PV=N/16;                // 8 k-tiles each
constexpr int S_COL=0, P_COL=64, O_COL=128;
constexpr uint32_t QKI2=0x10200490u;                    // 2SM QK: m_dim=16(M=256),n_dim=16(N=128),bf16,F32,K-major
constexpr uint32_t PVI2=0x10210490u;                    // 2SM PV: m_dim=16,n_dim=16(HDV=128),bf16,F32, V MN-major(b_major=1)
constexpr float SCALE=0.08838834764f;                   // 1/sqrt(128)

__global__ void __cluster_dims__(2,1,1) __launch_bounds__(128)
attn2sm(const __nv_bfloat16* Qg,const __nv_bfloat16* Kg,const __nv_bfloat16* Vg,float* Og){
    __shared__ __align__(1024) __nv_bfloat16 sQ[MH*HD];
    __shared__ __align__(1024) __nv_bfloat16 sK[(HD/64)*8192];  // 64 keys, koff-128 addressing
    __shared__ __align__(1024) __nv_bfloat16 sV[NH? MH:0>0? 0:0 + (128*HDVH)]; // 128 keys x 64 dv (voff, no block jump)
    __shared__ __align__(8) uint32_t s_base;
    __shared__ __align__(8) uint64_t s_mbar;
    const int tid=threadIdx.x, warp=tid>>5;
    const int rank=blockIdx.x&1; const bool leader=(rank==0);

    for(int i=tid;i<MH*HD;i+=128){ int r=i/HD,c=i%HD; sQ[koff(r,c)]=Qg[(rank*MH+r)*HD+c]; }
    for(int i=tid;i<NH*HD;i+=128){ int r=i/HD,c=i%HD; sK[koff(r,c)]=Kg[(rank*NH+r)*HD+c]; }   // this CTA's 64 keys
    for(int i=tid;i<128*HDVH;i+=128){ int key=i/HDVH,dv=i%HDVH; sV[voff(key,dv)]=Vg[key*HDV + (rank*HDVH+dv)]; } // this CTA's 64 dv-cols, all 128 keys
    asm volatile("fence.proxy.async.shared::cta;");
    __syncthreads();

    if(warp==0) tmem_alloc2(smem_u32(&s_base),256);
    if(warp==0) tmem_relinquish2();
    if(tid==0) asm volatile("mbarrier.init.shared.b64 [%0], 1;"::"r"(smem_u32(&s_mbar)));
    __syncthreads();
    const uint32_t base=s_base, mbar=smem_u32(&s_mbar);

    // ---- QK: S[256,128] = Q*K^T  (leader issues cta_group::2) ----
    if(leader && warp==0){
        uint64_t qd0=make_desc(smem_u32(sQ),16,1024,2), kd0=make_desc(smem_u32(sK),16,1024,2);
        for(int kb=0;kb<NKT_QK;++kb){ uint64_t qd=desc_add(qd0,qk_doff(kb)),kd=desc_add(kd0,qk_doff(kb)); uint32_t sc=(kb>0)?1u:0u;
            asm volatile("{ .reg .pred lead,p; elect.sync _|lead,-1; setp.ne.b32 p,%4,0;\n"
                "  @lead tcgen05.mma.cta_group::2.kind::f16 [%0], %1, %2, %3, {%5,%6,%7,%8,%9,%10,%11,%12}, p; }"
                ::"r"(base+S_COL),"l"(qd),"l"(kd),"r"(QKI2),"r"(sc),
                  "r"(0u),"r"(0u),"r"(0u),"r"(0u),"r"(0u),"r"(0u),"r"(0u),"r"(0u)); }
        uint16_t cm=0x3; asm volatile("{ .reg .pred lead; elect.sync _|lead,-1;\n"
            "  @lead tcgen05.commit.cta_group::2.mbarrier::arrive::one.shared::cluster.multicast::cluster.b64 [%0], %1; }"
            ::"r"(mbar),"h"(cm)); }
    asm volatile("{ .reg .pred P;\nA: mbarrier.try_wait.parity.shared.b64 P,[%0],0,10000000;\n @P bra B; bra A;\nB: }"::"r"(mbar));
    tmem_fence(); __syncthreads();

    // ---- per-CTA softmax over this CTA's 128 rows (row = tid) ----
    float sreg[N]; float rmax=-INFINITY;
    for(int c=0;c<N;++c){ uint32_t bb=tmem_ld(base+S_COL+((uint32_t)tid<<16)+c); float sv; memcpy(&sv,&bb,4); sv*=SCALE; sreg[c]=sv; rmax=fmaxf(rmax,sv); }
    tmem_wait_ld();
    float ps=0.f; const float LOG2E=1.4426950408889634f;
    for(int c=0;c<N;++c){ float p=ex2f((sreg[c]-rmax)*LOG2E); sreg[c]=p; ps+=p; }
    for(int c=0;c<N/2;++c) tmem_st(base+P_COL+((uint32_t)tid<<16)+c, pack16b(sreg[2*c],sreg[2*c+1]));
    tmem_wait_st();
    if(tid==0) asm volatile("mbarrier.init.shared.b64 [%0], 1;"::"r"(mbar));
    __syncthreads();

    // ---- PV: O[256,128] = P*V  (leader issues cta_group::2, TS form: A=P from tmem) ----
    if(leader && warp==0){
        uint64_t vd0=make_desc(smem_u32(sV),16384,1024,2);
        for(int kb=0;kb<NKT_PV;++kb){ uint64_t vd=desc_add(vd0,v_doff(kb)); uint32_t sc=(kb>0)?1u:0u; uint32_t pa=base+P_COL+(uint32_t)(kb*8);
            asm volatile("{ .reg .pred lead,p; elect.sync _|lead,-1; setp.ne.b32 p,%4,0;\n"
                "  @lead tcgen05.mma.cta_group::2.kind::f16 [%0], [%1], %2, %3, {%5,%6,%7,%8,%9,%10,%11,%12}, p; }"
                ::"r"(base+O_COL),"r"(pa),"l"(vd),"r"(PVI2),"r"(sc),
                  "r"(0u),"r"(0u),"r"(0u),"r"(0u),"r"(0u),"r"(0u),"r"(0u),"r"(0u)); }
        uint16_t cm=0x3; asm volatile("{ .reg .pred lead; elect.sync _|lead,-1;\n"
            "  @lead tcgen05.commit.cta_group::2.mbarrier::arrive::one.shared::cluster.multicast::cluster.b64 [%0], %1; }"
            ::"r"(mbar),"h"(cm)); }
    asm volatile("{ .reg .pred P;\nC: mbarrier.try_wait.parity.shared.b64 P,[%0],0,10000000;\n @P bra D; bra C;\nD: }"::"r"(mbar));
    tmem_fence(); __syncthreads();

    // ---- readback O for this CTA's 128 rows, normalize by row-sum ----
    float inv=(ps>0.f)?1.f/ps:0.f;
    for(int d=0;d<HDV;++d){ uint32_t bb=tmem_ld(base+O_COL+((uint32_t)tid<<16)+d); tmem_wait_ld(); float o; memcpy(&o,&bb,4);
        Og[(rank*MH+tid)*HDV+d]=o*inv; }
    __syncthreads();
    if(warp==0) tmem_dealloc2(base,256);
}

int main(){
    ORC_CHECK(cudaSetDevice(0));
    cudaDeviceProp p{}; ORC_CHECK(cudaGetDeviceProperties(&p,0)); std::printf("device: %s cc %d.%d\n",p.name,p.major,p.minor);
    std::vector<uint16_t> Qh,Kh,Vh; orc::fill_bf16(Qh,M*HD,1); orc::fill_bf16(Kh,N*HD,2); orc::fill_bf16(Vh,N*HDV,3);
    __nv_bfloat16 *dQ,*dK,*dV; float* dO;
    ORC_CHECK(cudaMalloc(&dQ,M*HD*2)); ORC_CHECK(cudaMalloc(&dK,N*HD*2)); ORC_CHECK(cudaMalloc(&dV,N*HDV*2)); ORC_CHECK(cudaMalloc(&dO,M*HDV*4));
    ORC_CHECK(cudaMemcpy(dQ,Qh.data(),M*HD*2,cudaMemcpyHostToDevice));
    ORC_CHECK(cudaMemcpy(dK,Kh.data(),N*HD*2,cudaMemcpyHostToDevice));
    ORC_CHECK(cudaMemcpy(dV,Vh.data(),N*HDV*2,cudaMemcpyHostToDevice));
    attn2sm<<<dim3(2,1,1),128>>>(dQ,dK,dV,dO);
    ORC_CHECK(cudaGetLastError()); ORC_CHECK(cudaDeviceSynchronize());
    std::vector<float> O(M*HDV); ORC_CHECK(cudaMemcpy(O.data(),dO,M*HDV*4,cudaMemcpyDeviceToHost));

    // fp32 reference attention: softmax(scale * Q K^T) V, per row m.
    double max_abs=0; int shown=0;
    for(int m=0;m<M;++m){
        std::vector<double> s(N); double mx=-1e30;
        for(int n=0;n<N;++n){ double acc=0; for(int k=0;k<HD;++k) acc+=(double)orc::bf16_bits_to_f32(Qh[m*HD+k])*(double)orc::bf16_bits_to_f32(Kh[n*HD+k]); s[n]=acc*(double)SCALE; mx=std::max(mx,s[n]); }
        double sum=0; for(int n=0;n<N;++n){ s[n]=std::exp(s[n]-mx); sum+=s[n]; }
        for(int d=0;d<HDV;++d){ double acc=0; for(int n=0;n<N;++n) acc+=s[n]*(double)orc::bf16_bits_to_f32(Vh[n*HDV+d]); double ref=acc/sum, got=O[m*HDV+d], err=std::fabs(got-ref);
            if(err>max_abs) max_abs=err; if(err>0.02 && shown<8){ std::printf("  bad m=%d d=%d got=%.4f ref=%.4f\n",m,d,got,ref); shown++; } }
    }
    std::printf("max_abs=%.5f\n",max_abs);
    bool pass=(max_abs<0.02);
    std::printf("%s: 2SM single-block attention (QK+softmax+PV, cta_group::2)\n", pass?"PASS":"FAIL");
    return pass?0:1;
}

