        for(int i=tid;i<TN*HDVH;i+=128){ int key=i/HDVH,dv=i%HDVH; int kk=key0+key; int gdv=rank*HDVH+dv;
            sV[voff(key,dv)]=(kk<seqlen_k && gdv<rhdv)?v[(size_t)(k0+kk)*hkv*rhdv+(size_t)hk*rhdv+gdv]:from_f<T>(0.f); }
