        if(leader && warp==0){                           // PV -> O (leader issues cta_group::2, TS form)
            uint64_t vd0=make_desc(smem_u32(sV),16384,1024,2);
            for(int kb=0;kb<NKT_PV;++kb){ uint64_t vd=desc_add(vd0,v_doff(kb)); uint32_t pa=base+P_COL+(uint32_t)(kb*8);
