    const uint32_t base=s_base;
    // softmax-like warps (0-3, tid 0..127) each own a tmem row; write cols 0,128,256,384,448 then read back.
    if(warp<4){
        uint32_t cols[5]={0u,128u,256u,384u,448u};
        for(int j=0;j<5;j++){ float v=(float)(tid*10+j); uint32_t b; memcpy(&b,&v,4); tmem_st(base+cols[j]+((uint32_t)tid<<16), b); }
        tmem_wait_st();
