    uint32_t rp=smem_u32(draw); uint32_t pad=((rp+1023u)&~1023u)-rp; __nv_bfloat16* dyn=(__nv_bfloat16*)((char*)draw+pad);
    __nv_bfloat16* sQ=dyn; __nv_bfloat16* sK=sQ+MH*HD;
    __shared__ __align__(8) uint64_t kvf, sf; __shared__ __align__(8) uint32_t s_base;
    const int tid=threadIdx.x, warp=tid>>5; const int rank=blockIdx.x&1; const bool leader=(rank==0);
    for(int i=tid;i<MH*HD;i+=512){ int r=i/HD,c=i%HD; sQ[koff(r,c)]=Qg[(rank*MH+r)*HD+c]; }
    if(warp==4){ tmem_alloc2(smem_u32(&s_base),512); tmem_relinquish2(); }
    if(tid==0){ mbar_init(smem_u32(&kvf),1); mbar_init(smem_u32(&sf),1); }
    if(warp==5 && (tid&31)==0 && leader) mbar_expect(smem_u32(&kvf), 2*NH*HD*2);  // leader-only, DOUBLED tx
    asm volatile("fence.proxy.async.shared::cta;");
    cluster_sync();                                 // one-time: expect_tx ordered before TMAs + base/mbars visible
    const uint32_t base=s_base, KVF=smem_u32(&kvf), SF=smem_u32(&sf);

    if(warp==5 && (tid&31)==0){                     // LOAD (both CTAs): own K half -> own smem, complete->leader kvf
        for(int cb=0;cb<KCB;cb++) tma_box_2sm(sK+cb*8192, &mapKh, cb*64, rank*NH, KVF);
    } else if(warp==4 && leader){                   // MMA (leader only): wait leader kvf, cta_group::2 QK, commit
        mbar_wait(KVF,0);
        uint64_t qd0=make_desc(smem_u32(sQ),16,1024,2), kd0=make_desc(smem_u32(sK),16,1024,2);
        for(int kb=0;kb<NKT_QK;++kb){ uint64_t qd=desc_add(qd0,qk_doff(kb)),kd=desc_add(kd0,qk_doff(kb)); mma_qk2(base+0,qd,kd,QKI2,(kb>0)?1u:0u); }
        mma_commit2(SF,0x3);
    }
