    }
    __syncthreads(); cluster_sync();
    if(warp==4) tmem_dealloc2(base,512);
}

static CUtensorMap make_map(const __nv_bfloat16* ptr, int rows_total, int hd, uint32_t box_rows){
    CUtensorMap m{}; uint64_t gdim[2]={(uint64_t)hd,(uint64_t)rows_total}; uint64_t gstride[1]={(uint64_t)(hd*sizeof(__nv_bfloat16))};
    uint32_t bdim[2]={64u,box_rows}; uint32_t estride[2]={1u,1u};
    DRV(cuTensorMapEncodeTiled(&m, CU_TENSOR_MAP_DATA_TYPE_BFLOAT16, 2, (void*)ptr, gdim, gstride, bdim, estride,
        CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE));
    return m;
}

